function countByStatus(rows: Array<{status: string}>): Record<string, number> {
  const result: Record<string, number> = {};
  for (const row of rows) result[row.status] = (result[row.status] ?? 0) + 1;
  return result;
}

cases.tests:
const rows = [{status: 'open'}, {status: 'done'}, {status: 'open'}];
const snapshot = JSON.stringify(rows);
const counts = countByStatus(rows);
if (JSON.stringify(counts) !== JSON.stringify({open: 2, done: 1})) throw new Error('wrong counts');
if (JSON.stringify(rows) !== snapshot) throw new Error('input changed');
if (Object.keys(countByStatus([])).length !== 0) throw new Error('empty input failed');

