function appendUnique(names, name) {
  if (names.includes(name)) return false;
  names.push(name);
  return true;
}

cases.tests:
const names = ['Ada'];
if (appendUnique(names, 'Lin') !== true) throw new Error('new return');
if (JSON.stringify(names) !== JSON.stringify(['Ada', 'Lin'])) throw new Error('new mutation');
if (appendUnique(names, 'Ada') !== false) throw new Error('old return');
if (JSON.stringify(names) !== JSON.stringify(['Ada', 'Lin'])) throw new Error('old mutation');

