use std::collections::HashSet;
fn dedupe_order(values: &[i32]) -> Vec<i32> {
    let mut seen = HashSet::new();
    values.iter().copied().filter(|value| seen.insert(*value)).collect()
}

cases.tests:
fn main() {
    assert_eq!(dedupe_order(&[3, 1, 3, 2, 1]), vec![3, 1, 2]);
    assert_eq!(dedupe_order(&[]), Vec::<i32>::new());
}

