#include <vector>
std::vector<int> running_totals(const std::vector<int>& values) {
    std::vector<int> result;
    int total = 0;
    for (int value : values) { total += value; result.push_back(total); }
    return result;
}

#include <stddef.h>
int find_first_even(const int *values, size_t length) {
    for (size_t index = 0; index < length; index++) {
        if (values[index] % 2 == 0) return (int)index;
    }
    return -1;
}

cases.tests:
#include <assert.h>
int main(void) {
    int a[] = {3, 7, 8, 10};
    int b[] = {1, 3, 5};
    assert(find_first_even(a, 4) == 2);
    assert(find_first_even(b, 3) == -1);
    assert(find_first_even(NULL, 0) == -1);
    return 0;
}

