package main
func WordLengths(words []string) map[string]int {
    result := make(map[string]int)
    for _, word := range words { result[word] = len(word) }
    return result
}

cases.tests:
func main() {
    got := WordLengths([]string{"go", "model", ""})
    if got["go"] != 2 || got["model"] != 5 || got[""] != 0 { panic("wrong lengths") }
    if len(WordLengths(nil)) != 0 { panic("nil failed") }
}
